    header_idx = None
    for i, line in enumerate(lines):
        if '| Feb.' in line:
            parts = line.split('|')
            if len(parts) > 12:
                months = []
                for p in parts:
                    p = p.strip().replace('.', '')
                    if p in ['Feb', 'Mar', 'Apr', 'May', 'June', 'July', 'Aug', 'Sept', 'Oct', 'Nov', 'Dec', 'Jan']:
                        months.append(p)
                if len(months) == 12:
                    header_idx = i
                    break

    if header_idx is None:
        return None

    header_line = lines[header_idx]
    parts = header_line.split('|')
    month_names = []
    for p in parts[1:]:
        p = p.strip().replace('.', '')
        if p in ['Feb', 'Mar', 'Apr', 'May', 'June', 'July', 'Aug', 'Sept', 'Oct', 'Nov', 'Dec', 'Jan']:
            month_names.append(p)

    for i in range(header_idx, min(len(lines), header_idx + 10)):
        line = lines[i]
        if 'Average yields of Treasury, corporate and municipal bonds by periods' in line:
            yield_line = line
            break
    else:
        return None

    parts = yield_line.split('|')
    values = []
    for p in parts[1:]:
        p = p.strip().replace('.0', '')
        if p.replace('-', '').isdigit():
            values.append(p)

    month_map = {'Feb': 2, 'Mar': 3, 'Apr': 4, 'May': 5, 'June': 6, 'July': 7, 
                 'Aug': 8, 'Sept': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12, 'Jan': 1}

    results = []
    for m, v in zip(month_names, values):
        month_num = month_map[m]
        if month_num >= 2:
            year = bul_year - 1
        else:
            year = bul_year
        results.append((year, month_num, float(v)))

    return results

# Extract all yields
