    result = get_yields_with_cal_months(ym)
    if result:
        for year, month, value in result:
            key = (year, month)
            if key not in all_yields:
                all_yields[key] = value
                print(f"{ym}: {(year, month)} = {value}")

print("\n=== Sorted yields by calendar month ===")
# Sort and display
sorted_keys = sorted(all_yields.keys())
for key in sorted_keys:
    year, month = key
    if (year == 1971 and month >= 1) or (year == 1972) or (year == 1973 and month <= 7):
        print(f"{year}-{month:02d}: {all_yields[key]}")
